"use strict";(self.webpackChunkknowledge_base=self.webpackChunkknowledge_base||[]).push([[191],{7443(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>a,default:()=>h,frontMatter:()=>i,metadata:()=>o,toc:()=>l});const o=JSON.parse('{"id":"books/effective-java/concurrency","title":"11. Concurrency","description":"Chapter overview","source":"@site/docs/books/effective-java/11-concurrency.md","sourceDirName":"books/effective-java","slug":"/books/effective-java/concurrency","permalink":"/knowledgebase/books/effective-java/concurrency","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":12,"frontMatter":{"title":"11. Concurrency","sidebar_position":12},"sidebar":"knowledgeSidebar","previous":{"title":"10. Exceptions","permalink":"/knowledgebase/books/effective-java/exceptions"},"next":{"title":"12. Serialization","permalink":"/knowledgebase/books/effective-java/serialization"}}');var s=n(4848),r=n(8453);const i={title:"11. Concurrency",sidebar_position:12},a="11. Concurrency",c={},l=[{value:"Chapter overview",id:"chapter-overview",level:2},{value:"Item 78: Synchronize access to shared mutable data",id:"item-78-synchronize-access-to-shared-mutable-data",level:2},{value:"Item 79: Avoid excessive synchronization",id:"item-79-avoid-excessive-synchronization",level:2},{value:"Item 80: Prefer executors, tasks, and streams to threads",id:"item-80-prefer-executors-tasks-and-streams-to-threads",level:2},{value:"Item 81: Prefer concurrency utilities to wait and notify",id:"item-81-prefer-concurrency-utilities-to-wait-and-notify",level:2},{value:"Item 82: Document thread safety",id:"item-82-document-thread-safety",level:2},{value:"Item 83: Use lazy initialization judiciously",id:"item-83-use-lazy-initialization-judiciously",level:2},{value:"Item 84: Don&#39;t depend on the thread scheduler",id:"item-84-dont-depend-on-the-thread-scheduler",level:2}];function d(e){const t={code:"code",h1:"h1",h2:"h2",header:"header",hr:"hr",p:"p",pre:"pre",strong:"strong",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"11-concurrency",children:"11. Concurrency"})}),"\n",(0,s.jsx)(t.h2,{id:"chapter-overview",children:"Chapter overview"}),"\n",(0,s.jsx)(t.p,{children:"This chapter covers concurrent programming: synchronize access to shared mutable data, prefer executors and tasks to threads, prefer concurrency utilities to wait/notify, document thread safety, use lazy initialization correctly, and don\u2019t depend on the thread scheduler. Correct use of concurrency avoids data races, deadlocks, and fragile behavior."}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsx)(t.h2,{id:"item-78-synchronize-access-to-shared-mutable-data",children:"Item 78: Synchronize access to shared mutable data"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Summary paragraph:"})," When multiple threads read or write shared mutable data, every read and write must be performed under appropriate synchronization (or use volatile for a single read/write of a single variable). Without synchronization, you get data races, and the visibility guarantees of the Java Memory Model don\u2019t apply; threads can see stale or inconsistent state."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Context:"})," The JMM allows threads to cache variables in registers or local memory unless there is a happens-before relationship (e.g. from synchronization or volatile). So one thread\u2019s write might not be visible to another unless they synchronize on the same monitor or use volatile."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Why it matters:"})," Data races cause undefined behavior: wrong results, infinite loops (e.g. \u201choisted\u201d read of a flag), or crashes. Synchronization (or volatile for simple flags) ensures visibility and ordering. Don\u2019t try to avoid synchronization for \u201cperformance\u201d without understanding the JMM; incorrect code is worse than slower correct code."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"What to do:"})," For shared mutable state, either: make the state immutable or effectively immutable; confine it to a single thread; or protect every access (read and write) with the same lock (or use volatile for a single variable used as a flag). Prefer higher-level constructs (concurrent collections, ExecutorService) over hand-written locking when they fit. Document the locking policy (which lock protects which state)."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Pitfalls / exceptions:"})," volatile gives visibility but not atomicity for compound actions (e.g. read-modify-write); use AtomicInteger, locking, or compare-and-swap. Double-checked locking is broken without volatile on the reference. Synchronization has cost; use when needed for correctness, then optimize if necessary."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Pros and cons:"})," Pros of correct synchronization: correct, predictable. Cons: complexity, possible deadlock. Pros of volatile: visibility for single variable. Cons: no atomicity for compound ops."]}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Quick example:"})}),"\n",(0,s.jsx)(t.pre,{children:(0,s.jsx)(t.code,{className:"language-java",children:"private static volatile boolean stop;\n// Writer: stop = true;\n// Reader: while (!stop) { ... }\n// Use volatile so the reader sees the write.\n"})}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsx)(t.h2,{id:"item-79-avoid-excessive-synchronization",children:"Item 79: Avoid excessive synchronization"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Summary paragraph:"})," Synchronization can cause deadlock, reduced throughput, and unexpected behavior (e.g. calling alien code under a lock). Keep synchronized blocks short; do not invoke external callbacks, user code, or methods that may be overridden while holding a lock. Consider using concurrent collections or splitting locks to reduce contention."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Context:"})," Holding a lock for a long time blocks other threads and increases deadlock risk. Invoking unknown code (callbacks, overridable methods) under a lock can lead to deadlock (if the callback tries to acquire another lock) or to poor performance (if the callback is slow). It can also cause livelock or reentrancy issues."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Why it matters:"})," Excessive synchronization serializes threads and can deadlock. Calling alien code under a lock is dangerous because you don\u2019t control what it does (it might lock, block, or take a long time). The \u201copen call\u201d principle: don\u2019t hold a lock when calling code you don\u2019t own."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"What to do:"})," Do as little as possible inside synchronized blocks. Move slow or blocking operations (I/O, external calls) outside the block. Don\u2019t call overridable methods or callbacks while holding a lock; do it before/after or in a copy of the data. Use concurrent collections (ConcurrentHashMap, etc.) to reduce lock scope. Consider lock splitting or non-blocking data structures for high contention."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Pitfalls / exceptions:"})," Copying data to call outside the lock can be expensive; balance with contention. Reentrant locks allow the same thread to re-enter, but that doesn\u2019t remove the risk of calling alien code (e.g. subclass method that acquires another lock)."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Pros and cons:"})," Pros of minimal locking: less deadlock, better throughput. Cons: design effort. Cons of holding locks during callbacks: deadlock, slow."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Quick example:"})," Copy the list of listeners inside the lock, then notify them outside the lock."]}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsx)(t.h2,{id:"item-80-prefer-executors-tasks-and-streams-to-threads",children:"Item 80: Prefer executors, tasks, and streams to threads"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Summary paragraph:"})," Prefer the ExecutorService framework (executors, tasks) over managing raw Threads. Use Executors to create thread pools, submit Runnable or Callable tasks, and get Futures. For parallel processing of bulk data, prefer parallel streams or the ForkJoin pool. This gives better separation of \u201cwhat runs\u201d from \u201chow many threads\u201d and avoids the overhead of creating threads directly."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Context:"})," Creating and starting a Thread for each unit of work is expensive and doesn\u2019t scale. ExecutorService provides thread pools, task submission, and lifecycle management. It\u2019s the standard way to run asynchronous or parallel work in Java."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Why it matters:"})," Thread creation has cost; pools reuse threads. ExecutorService gives you control over pool size, shutdown, and result handling (Future). Parallel streams integrate with the common pool and are convenient for data parallelism. Raw threads are for rare cases (e.g. need a specific Thread subclass)."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"What to do:"})," Use Executors.newFixedThreadPool, newCachedThreadPool, or custom ThreadPoolExecutor for task execution. Submit Runnable or Callable; use Future to get results or cancel. For bulk operations over collections, use parallelStream() or a custom executor with the right size. Shut down the executor when the application is done (shutdown, awaitTermination). Prefer higher-level APIs (CompletableFuture, parallel streams) when they fit."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Pitfalls / exceptions:"})," Don\u2019t use the default ForkJoinPool for blocking I/O (it has limited parallelism). Size the pool appropriately; too many threads can hurt. Uncaught exceptions in tasks can be lost; use a custom ThreadFactory or handle in the task. Don\u2019t submit tasks that never complete (or use timeouts)."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Pros and cons:"})," Pros: reuse, control, Futures, standard. Cons: need to choose and tune pool. Pros of parallel streams: simple for data parallelism. Cons: shared pool, not for I/O-bound."]}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Quick example:"})}),"\n",(0,s.jsx)(t.pre,{children:(0,s.jsx)(t.code,{className:"language-java",children:"ExecutorService exec = Executors.newFixedThreadPool(4);\nFuture<Result> f = exec.submit(() -> compute());\nResult r = f.get(5, TimeUnit.SECONDS);\nexec.shutdown();\n"})}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsx)(t.h2,{id:"item-81-prefer-concurrency-utilities-to-wait-and-notify",children:"Item 81: Prefer concurrency utilities to wait and notify"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Summary paragraph:"})," Use the high-level concurrency utilities (java.util.concurrent) instead of wait/notify. Use BlockingQueue for producer-consumer, CountDownLatch for \u201cwait until N events,\u201d Semaphore for bounded resources, CyclicBarrier for phased coordination. These are clearer and less error-prone than hand-written wait/notify."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Context:"})," wait(), notify(), and notifyAll() are low-level and easy to misuse (wrong lock, missed signal, spurious wakeup). The concurrent package provides queues, latches, barriers, and locks that express intent and handle edge cases."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Why it matters:"})," wait/notify require correct locking, condition checking in a loop, and correct notify (all vs one). Concurrency utilities encapsulate these patterns and are tested. They also support timeouts and interruption cleanly."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"What to do:"})," Use BlockingQueue (LinkedBlockingQueue, ArrayBlockingQueue) for producer-consumer. Use CountDownLatch for \u201cstart when N things are ready\u201d or \u201cwait until N things done.\u201d Use Semaphore for limiting concurrency. Use CyclicBarrier for multi-step parallel phases. Use Phaser for dynamic parties. Use Lock and Condition only when you need something the standard utilities don\u2019t provide. If you must use wait/notify, always wait in a loop that checks the condition and use the same lock for wait and notify."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Pitfalls / exceptions:"})," wait() must be in a loop: while (!condition) wait();. Always use the same object\u2019s monitor for wait and notify. Prefer notifyAll() unless you can prove that only one waiter needs to run (notify() is error-prone). Document the condition and locking."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Pros and cons:"})," Pros of utilities: clarity, correctness, timeouts. Cons of wait/notify: easy to get wrong."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Quick example:"})," Use ",(0,s.jsx)(t.code,{children:"BlockingQueue.take()"})," and ",(0,s.jsx)(t.code,{children:"put()"})," instead of a hand-written wait/notify queue."]}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsx)(t.h2,{id:"item-82-document-thread-safety",children:"Item 82: Document thread safety"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Summary paragraph:"})," Document the thread-safety guarantees of every class: immutable, thread-safe, not thread-safe, or conditionally thread-safe (and under what conditions). Document any locking strategy and which locks protect which state. This lets users use the class correctly in concurrent contexts."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Context:"})," Callers need to know whether they can share an instance across threads and whether they must synchronize. Without documentation, they may assume the wrong thing (e.g. that a class is thread-safe when it isn\u2019t, or that they must lock when the class already does)."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Why it matters:"})," Misuse leads to data races or unnecessary locking. Documenting \u201cnot thread-safe\u201d or \u201cthread-safe\u201d (and how) sets expectations. Conditionally thread-safe classes (e.g. \u201csafe when used from one thread, or when synchronized externally\u201d) must say so clearly."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"What to do:"})," In the class-level Javadoc, state the thread-safety level: immutable, thread-safe, not thread-safe, or conditionally thread-safe (with the condition). If the class uses locks, document which lock protects which state (e.g. \u201call access to field X is guarded by this\u201d). If you use a public lock (e.g. for client-side locking), document it. Use @implNote or similar for implementation details that affect thread safety."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Pitfalls / exceptions:"})," Don\u2019t promise thread safety if the class isn\u2019t safe; that leads to bugs. If you change the thread-safety policy in a later version, document it as a breaking change. Static factories that return shared instances (e.g. singletons) should document thread safety of the returned object."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Pros and cons:"})," Pros: clear contract, fewer misuse. Cons: must keep docs accurate."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Quick example:"})," \u201cThis class is not thread-safe. External synchronization is required if instances are shared between threads.\u201d"]}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsx)(t.h2,{id:"item-83-use-lazy-initialization-judiciously",children:"Item 83: Use lazy initialization judiciously"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Summary paragraph:"})," Lazy initialization defers creating a field until first use. It can save startup time or avoid unnecessary allocation but adds complexity and can require synchronization. For static fields, prefer the lazy holder idiom. For instance fields, prefer double-check with volatile or just initialize in the constructor if cheap. Avoid lazy init when it doesn\u2019t bring a clear benefit."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Context:"})," Sometimes you want to create a heavy object only when it\u2019s first needed. That requires either synchronizing every access (slow) or a more subtle pattern (double-check, holder class). Wrong patterns can expose partially constructed objects or miss visibility."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Why it matters:"})," Incorrect lazy init can cause multiple initialization, visibility bugs (thread sees null or half-initialized object), or unnecessary locking. The right pattern depends on static vs instance, and whether the cost of synchronization is acceptable."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"What to do:"})," For static fields: use the lazy holder class idiom (a static nested class whose field is initialized when the class is loaded; JVM guarantees safe publication). For instance fields: if the field is almost always used, initialize in constructor or at declaration. If it\u2019s rarely used and expensive, use double-check with volatile (check twice, synchronize once, assign with volatile so it\u2019s visible). Don\u2019t use lazy init for cheap objects or when you don\u2019t have a clear benefit."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Pitfalls / exceptions:"})," Double-check requires the field to be volatile (or use a final field set in a synchronized block with a proper happens-before). The \u201cholder\u201d idiom only works for static fields. Avoid lazy init of many fields if it complicates the code; sometimes eager init is simpler."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Pros and cons:"})," Pros: defer cost. Cons: complexity, risk of bugs. Eager init is simpler when cost is low."]}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Quick example:"})}),"\n",(0,s.jsx)(t.pre,{children:(0,s.jsx)(t.code,{className:"language-java",children:"private static class Holder {\n    static final FieldType FIELD = compute();\n}\nstatic FieldType getField() { return Holder.FIELD; }\n"})}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsx)(t.h2,{id:"item-84-dont-depend-on-the-thread-scheduler",children:"Item 84: Don't depend on the thread scheduler"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Summary paragraph:"})," Do not rely on the thread scheduler (e.g. thread priorities, yield) for correctness. Thread scheduling is platform-dependent and can change. Correctness should not depend on which thread runs when. Use adequate parallelism (enough runnable threads, but not so many that the scheduler is overloaded) and structure the program so that it works regardless of scheduling decisions."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Context:"})," Thread priorities and yield() are hints; the scheduler can ignore them. Programs that \u201cwork\u201d only when threads run in a certain order or with certain priorities are fragile. They may fail under load, on different OSes, or with different JVM versions."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Why it matters:"})," Depending on scheduling for correctness leads to bugs that are hard to reproduce (\u201cworks on my machine\u201d). Priorities can cause starvation or priority inversion. The right approach is to use enough threads (and the right concurrency constructs) so that the program is correct and responsive without relying on scheduling details."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"What to do:"})," Ensure there are enough runnable threads (e.g. not blocked on I/O without a pool) so that progress can be made. Don\u2019t use thread priority for correctness; use it only for tuning responsiveness if needed. Avoid busy-waiting (spin loops); use wait/notify or blocking structures. Don\u2019t rely on yield() or sleep() for correctness. Use proper synchronization and coordination (latches, queues) so that behavior doesn\u2019t depend on who runs first."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Pitfalls / exceptions:"})," Thread priority can help with responsiveness (e.g. giving a UI thread a boost) but shouldn\u2019t be required for correctness. Reducing runnable threads (e.g. using a bounded pool) can improve throughput by reducing contention; that\u2019s tuning, not correctness."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Pros and cons:"})," Pros of not depending on scheduler: portable, reliable. Cons of relying on it: fragile, non-portable."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Quick example:"})," Use a CountDownLatch so that \u201cstart when ready\u201d doesn\u2019t depend on which thread runs first; don\u2019t use a busy loop and hope the right thread runs."]})]})}function h(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>i,x:()=>a});var o=n(6540);const s={},r=o.createContext(s);function i(e){const t=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),o.createElement(r.Provider,{value:t},e.children)}}}]);